-- Admin / ops queries: grants, warehouses, session, metadata
USE ROLE SYSADMIN;
USE WAREHOUSE compute_wh;
USE DATABASE analytics;
USE SCHEMA analytics.public;
USE analytics.public;
SHOW TABLES;
SHOW TABLES IN SCHEMA analytics.public;
SHOW TABLES LIKE 'ORD%' IN DATABASE analytics;
SHOW SCHEMAS IN DATABASE analytics;
SHOW COLUMNS IN TABLE orders;
SHOW GRANTS TO ROLE analyst;
SHOW GRANTS ON TABLE orders;
SHOW WAREHOUSES;
SHOW USERS;
SHOW PARAMETERS LIKE 'TIMEZONE' IN SESSION;
SHOW VIEWS;
SHOW TASKS;
SHOW STAGES;
DESCRIBE TABLE orders;
DESC VIEW v_orders;
DESCRIBE STAGE my_stage;
CREATE WAREHOUSE IF NOT EXISTS etl_wh WITH WAREHOUSE_SIZE = 'XSMALL' AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE;
ALTER WAREHOUSE etl_wh SET WAREHOUSE_SIZE = 'LARGE';
ALTER WAREHOUSE etl_wh SUSPEND;
CREATE ROLE analyst;
GRANT ROLE analyst TO USER jdoe;
GRANT USAGE ON WAREHOUSE compute_wh TO ROLE analyst;
GRANT USAGE ON DATABASE analytics TO ROLE analyst;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics.public TO ROLE analyst;
GRANT SELECT ON FUTURE TABLES IN SCHEMA analytics.public TO ROLE analyst;
GRANT ALL PRIVILEGES ON TABLE orders TO ROLE etl_role;
REVOKE SELECT ON TABLE orders FROM ROLE analyst;
CREATE USER jdoe PASSWORD = 'Temp#1234' DEFAULT_ROLE = analyst MUST_CHANGE_PASSWORD = TRUE;
ALTER USER jdoe SET DISABLED = TRUE;
ALTER SESSION SET TIMEZONE = 'UTC';
ALTER SESSION SET QUERY_TAG = 'nightly_etl';
ALTER SESSION SET TIMESTAMP_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS';
SET my_var = 10;
SELECT $my_var + 1;
SELECT * FROM IDENTIFIER('orders') LIMIT 5;
SELECT * FROM snowflake.account_usage.query_history WHERE start_time > DATEADD(day, -1, CURRENT_TIMESTAMP()) ORDER BY total_elapsed_time DESC LIMIT 50;
SELECT warehouse_name, SUM(credits_used) AS credits FROM snowflake.account_usage.warehouse_metering_history WHERE start_time >= DATEADD(month, -1, CURRENT_DATE()) GROUP BY 1 ORDER BY 2 DESC;
SELECT table_schema, table_name, row_count, bytes / POWER(1024, 3) AS gb FROM information_schema.tables WHERE table_type = 'BASE TABLE' ORDER BY bytes DESC;
SELECT SYSTEM$CLUSTERING_INFORMATION('orders', '(order_date)');
SELECT SYSTEM$TYPEOF(1);
SELECT GET_DDL('TABLE', 'orders');
ALTER ACCOUNT SET TIMEZONE = 'UTC';
ALTER TABLE orders ADD ROW ACCESS POLICY rap ON (region);
CREATE OR REPLACE MASKING POLICY email_mask AS (val STRING) RETURNS STRING -> CASE WHEN CURRENT_ROLE() IN ('ADMIN') THEN val ELSE '***' END;
ALTER TABLE users MODIFY COLUMN email SET MASKING POLICY email_mask;
CREATE TAG pii_tag;
ALTER TABLE users SET TAG pii_tag = 'true';
EXPLAIN SELECT * FROM orders;
